{"content": "#include "common.h"

#include <chrono>
#include <cmath>
#include <cstdio>
#include <random>

Sim make_sim(int n) {
  Sim s;
  s.n = n;
  s.size = 2.0 * std::sqrt((double)n);
  std::mt19937 rng(SEED);
  std::uniform_real_distribution<double> u(0.0, 1.0);
  s.x.resize(n);
  s.y.resize(n);
  s.vx.resize(n);
  s.vy.resize(n);
  for (int i = 0; i < n; i++) {
    s.x[i] = u(rng) * s.size;
    s.y[i] = u(rng) * s.size;
    s.vx[i] = (u(rng) * 2.0 - 1.0) * 0.5;
    s.vy[i] = (u(rng) * 2.0 - 1.0) * 0.5;
  }
  return s;
}

// O(n) force step over the whole domain using uniform spatial bins of size RC.
// Each particle only inspects the 3x3 neighborhood of cells. Per-particle work
// is independent, so the loop is safe to parallelize (bit-identical results).
void step_full(Sim& s) {
  const int n = s.n;
  if (n == 0) return;
  const double S = s.size;
  const int cells = (int)(S / RC + 0.5);
  const int nc = cells * cells;

  std::vector<int> count(nc, 0), start(nc + 1, 0), pidx(n);
  for (int i = 0; i < n; i++) {
    int cx = (int)(s.x[i] / RC);
    int cy = (int)(s.y[i] / RC);
    if (cx >= cells) cx = cells - 1;
    if (cy >= cells) cy = cells - 1;
    count[cy * cells + cx]++;
  }
  int run = 0;
  for (int c = 0; c < nc; c++) {
    start[c] = run;
    run += count[c];
    count[c] = 0;
  }
  start[nc] = run;
  for (int i = 0; i < n; i++) {
    int cx = (int)(s.x[i] / RC);
    int cy = (int)(s.y[i] / RC);
    if (cx >= cells) cx = cells - 1;
    if (cy >= cells) cy = cells - 1;
    int c = cy * cells + cx;
    pidx[start[c] + count[c]++] = i;
  }

  const double rc2 = RC * RC;
  #pragma omp parallel for schedule(static)
  for (int i = 0; i < n; i++) {
    int cx = (int)(s.x[i] / RC);
    int cy = (int)(s.y[i] / RC);
    if (cx >= cells) cx = cells - 1;
    if (cy >= cells) cy = cells - 1;
    double fxi = 0.0, fyi = 0.0;
    for (int oy = -1; oy <= 1; oy++) {
      int ay = cy + oy;
      if (ay < 0 || ay >= cells) continue;
      for (int ox = -1; ox <= 1; ox++) {
        int ax = cx + ox;
        if (ax < 0 || ax >= cells) continue;
        int c = ay * cells + ax;
        for (int k = start[c]; k < start[c + 1]; k++) {
          int j = pidx[k];
          if (j == i) continue;
          double dx = s.x[j] - s.x[i];
          double dy = s.y[j] - s.y[i];
          double r2 = dx * dx + dy * dy;
          if (r2 >= rc2 || r2 < 1e-12) continue;
          double r = std::sqrt(r2);
          double f = F0 * (1.0 - r / RC) / r;  // repulsive, away from j
          fxi -= f * dx;
          fyi -= f * dy;
        }
      }
    }
    s.vx[i] += DT * fxi;
    s.vy[i] += DT * fyi;
    if (s.vx[i] > VMAX) s.vx[i] = VMAX;
    else if (s.vx[i] < -VMAX) s.vx[i] = -VMAX;
    if (s.vy[i] > VMAX) s.vy[i] = VMAX;
    else if (s.vy[i] < -VMAX) s.vy[i] = -VMAX;
    s.x[i] += DT * s.vx[i];
    s.y[i] += DT * s.vy[i];
    s.x[i] = std::fmod(s.x[i], S);
    if (s.x[i] < 0.0) s.x[i] += S;
    s.y[i] = std::fmod(s.y[i], S);
    if (s.y[i] < 0.0) s.y[i] += S;
  }
}

void pair_metrics(const Sim& s, double& amin, double& aavg) {
  const int n = s.n;
  if (n < 2) {
    amin = 0.0;
    aavg = 0.0;
    return;
  }
  const double S = s.size;
  if ((long long)n <= 100000LL) {
    // Exact all-pairs.
    double best = 1e300, sum = 0.0;
    long cnt = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        double dx = s.x[j] - s.x[i];
        double dy = s.y[j] - s.y[i];
        double d = std::sqrt(dx * dx + dy * dy);
        if (d < best) best = d;
        sum += d;
        cnt++;
      }
    }
    amin = best;
    aavg = (cnt > 0) ? (double)sum / (double)cnt : 0.0;
    return;
  }
  // Large n: min via expanding binned rings; mean via fixed-seed sampling.
  const int cells = (int)(S + 0.5);
  std::vector<std::vector<int>> grid(cells * cells);
  for (int i = 0; i < n; i++) {
    int cx = (int)s.x[i];
    int cy = (int)s.y[i];
    if (cx >= cells) cx = cells - 1;
    if (cy >= cells) cy = cells - 1;
    grid[cy * cells + cx].push_back(i);
  }
  double best = 1e300;
  for (int i = 0; i < n; i++) {
    int cx = (int)s.x[i];
    int cy = (int)s.y[i];
    if (cx >= cells) cx = cells - 1;
    if (cy >= cells) cy = cells - 1;
    double bi = 1e300;
    int w = 1;
    for (; w <= cells; w = w * 2) {
      int c0x = cx - w, c1x = cx + w;
      int c0y = cy - w, c1y = cy + w;
      for (int gy = c0y; gy <= c1y; gy++) {
        if (gy < 0 || gy >= cells) continue;
        for (int gx = c0x; gx <= c1x; gx++) {
          if (gx < 0 || gx >= cells) continue;
          const std::vector<int>& cell = grid[gy * cells + gx];
          for (size_t k = 0; k < cell.size(); k++) {
            int j = cell[k];
            if (j == i) continue;
            double dx = s.x[j] - s.x[i];
            double dy = s.y[j] - s.y[i];
            double d = std::sqrt(dx * dx + dy * dy);
            if (d < bi) bi = d;
          }
        }
      }
      // Window of half-size w covers all partners closer than w; once it
      // exceeds the best distance found, the nearest neighbor is settled.
      if (bi < 1e299 && (double)w >= bi) break;
    }
    if (bi < best) best = bi;
  }
  amin = best;
  std::mt19937 rng(SEED + 1000003U);
  std::uniform_int_distribution<int> ui(0, n - 1);
  const int M = 2000000;
  double sum = 0.0;
  long cnt = 0;
  for (int k = 0; k < M; k++) {
    int i = ui(rng);
    int j = ui(rng);
    if (i == j) continue;
    double dx = s.x[j] - s.x[i];
    double dy = s.y[j] - s.y[i];
    sum += std::sqrt(dx * dx + dy * dy);
    cnt++;
  }
  aavg = (cnt > 0) ? sum / (double)cnt : 0.0;
}

void report(const Sim& s, double t, const char* worker_label, int nworkers,
            const std::string& out, const std::string& sum) {
  const int n = s.n;
  double amin = 0.0, aavg = 0.0;
  pair_metrics(s, amin, aavg);

  // Fraction of particles that moved away from the initial configuration.
  Sim s0 = make_sim(n);
  long moved = 0;
  for (int i = 0; i < n; i++) {
    if (std::abs(s.x[i] - s0.x[i]) > 1e-9 || std::abs(s.y[i] - s0.y[i]) > 1e-9)
      moved++;
  }

  if (worker_label != nullptr)
    printf("%s = %d\n", worker_label, nworkers);
  printf("n = %d, simulation time = %.6f seconds\n", n, t);
  printf("absmin = %.6f\n", amin);
  printf("absavg = %.6f\n", aavg);
  printf("moved = %ld / %d\n", moved, n);
  fflush(stdout);

  FILE* fo = std::fopen(out.c_str(), "w");
  if (fo != nullptr) {
    fprintf(fo, "%d %.6f\n", n, s.size);
    for (int i = 0; i < n; i++)
      fprintf(fo, "%.6f %.6f\n", s.x[i], s.y[i]);
    std::fclose(fo);
  }
  FILE* fs = std::fopen(sum.c_str(), "w");
  if (fs != nullptr) {
    if (worker_label != nullptr)
      fprintf(fs, "%d %d %.6f\n", n, nworkers, t);
    else
      fprintf(fs, "%d %.6f\n", n, t);
    std::fclose(fs);
  }
}
