{"content": "// MPI 2D particle simulator. Domain decomposition into a 2D grid of blocks
// with halo (ghost) exchange of a RC-thick layer each step; O(n/P) local
// binned forces. When a block would hold fewer than 3*RC of space (tiny
// problems / many ranks) the program falls back to static ownership with
// one global binning per step, which stays O(n log P + n).
#include "common.h"
#include "mpi.h"

#include <algorithm>
#include <cstdlib>
#include <string>
#include <utility>
#include <vector>

int main(int argc, char** argv) {
  int rank = 0, nprocs = 1;
  MPI_Init(&argc, &argv);
  MPI_Comm_rank(MPI_COMM_WORLD, &rank);
  MPI_Comm_size(MPI_COMM_WORLD, &nprocs);

  int n = -1;
  std::string out = "/app/mpi.txt";
  std::string sum = "/app/mpi_summary.txt";
  for (int i = 1; i < argc; i++) {
    std::string a = argv[i];
    if (a == "-n" && i + 1 < argc) {
      n = std::atoi(argv[++i]);
    } else if (a == "-o" && i + 1 < argc) {
      out = argv[++i];
    } else if (a == "-s" && i + 1 < argc) {
      sum = argv[++i];
    }
  }
  if (n <= 0) {
    if (rank == 0)
      fprintf(stderr, "usage: mpirun -np <P> ./mpi -n <particles> [-o positions.txt] [-s summary.txt]\n");
    MPI_Abort(MPI_COMM_WORLD, 1);
  }

  Sim s = make_sim(n);
  const double S = s.size;
  const int RCi = 1;  // halo thickness in integer cells (cell size = 1.0)

  // ----- 2D block layout -------------------------------------------------
  int px = 1, py = 1;
  while (px * py < nprocs) {
    if ((nprocs / (px + 1)) >= (nprocs / py) || py >= px + 1)
      px++;
    else
      py++;
  }
  int cr[4];  // cell extents of my block
  {
    int rx = rank % px, ry = rank / px;
    int sx = S / px, sy = S / py;
    int x0 = (int)std::llround(rx * sx);
    int x1 = (rx == px - 1) ? (int)S : (int)std::llround((rx + 1) * sx);
    int y0 = (int)std::llround(ry * sy);
    int y1 = (ry == py - 1) ? (int)S : (int)std::llround((ry + 1) * sy);
    cr[0] = x0; cr[1] = x1; cr[2] = y0; cr[3] = y1;
  }
  int local_cells = (cr[1] - cr[0]) * (cr[3] - cr[2]);
  int ghost_cells = (cr[1] - cr[0] + 2 * RCi) * (cr[3] - cr[2] + 2 * RCi);
  int nb = 2 * nprocs;
  int nbr[8] = {0, 0, 0, 0, 0, 0, 0, 0};  // 0:+x 1:-x 2:+y 3:-y 4:+x+y 5:-x-y 6:+y-x 7:-y-x
  bool dynamic = (cr[1] - cr[0] >= 3 * RCi) && (cr[3] - cr[2] >= 3 * RCi) && (local_cells > 0);
  {
    int px0 = cr[0], px1 = cr[1], py0 = cr[2], py1 = cr[3];
    int rx = rank % px, ry = rank / px;
    auto inb = [&](int x, int y) { return x >= 0 && x < (int)S && y >= 0 && y < (int)S; };
    int cand[8][2];
    int cx[8] = {px1, px0 - 1, py1, py0 - 1, px1, px0 - 1, py1, py0 - 1};
    int cy[8] = {py0, py0, py0, py0, py1 - 1, py1 - 1, py1 - 1, py1 - 1};
    for (int d = 0; d < 8; d++) {
      int x = (d == 0 || d == 4 || d == 5) ? (d == 0 ? px1 : px0 - 1) : ((d == 6 || d == 7) ? px0 - 1 : px1);
      int y = (d == 2 || d == 3 || d == 4) ? (d == 2 ? py1 : py0 - 1) : ((d == 6 || d == 7) ? py1 - 1 : py0);
      (void)x; (void)y;
      int gx = (d & 1) ? px0 - 1 : px1;
      int gy = (d & 2) ? py0 - 1 : py1;
      int nx = gx, ny = gy;
      // map the neighbor block coordinate
      int nrx = rx + ((d & 1) ? -1 : 1);
      int nry = ry + ((d & 2) ? -1 : 1);
      int found = -1;
      if (nrx == rx && nry == ry) found = rank;
      else {
        int fx = nrx, fy = nry;
        if (nrx < 0 || nrx >= px || nry < 0 || nry >= py) {
          fx = -1; fy = -1;
        }
        if (inb(gx, gy)) {
          // which block owns the point just outside my edge?
          int ownx = 0, owny = 0;
          if (inb(px1, (py0 + py1) / 2)) {
            for (int k = 0; k < px; k++) {
              int bx0 = (int)std::llround(k * S / px);
              int bx1 = (k == px - 1) ? (int)S : (int)std::llround((k + 1) * S / px);
              if (px1 >= bx0 && px1 < bx1) { ownx = k; break; }
            }
          } else if (inb(px0 - 1, (py0 + py1) / 2)) {
            for (int k = 0; k < px; k++) {
              int bx0 = (int)std::llround(k * S / px);
              int bx1 = (k == px - 1) ? (int)S : (int)std::llround((k + 1) * S / px);
              if (px0 - 1 >= bx0 && px0 - 1 < bx1) { ownx = k; break; }
            }
          }
          if (inb((px0 + px1) / 2, py1)) {
            for (int k = 0; k < py; k++) {
              int by0 = (int)std::llround(k * S / py);
              int by1 = (k == py - 1) ? (int)S : (int)std::llround((k + 1) * S / py);
              if (py1 >= by0 && py1 < by1) { owny = k; break; }
            }
          } else if (inb((px0 + px1) / 2, py0 - 1)) {
            for (int k = 0; k < py; k++) {
              int by0 = (int)std::llround(k * S / py);
              int by1 = (k == py - 1) ? (int)S : (int)std::llround((k + 1) * S / py);
              if (py0 - 1 >= by0 && py0 - 1 < by1) { owny = k; break; }
            }
          }
          if (nrx < 0 || nrx >= px || nry < 0 || nry >= py || !inb(gx, gy)) {
            // wrap-around neighbor: use ownership of the periodic image
            int wx = (nrx < 0) ? px - 1 : 0;
            int wy = (nry < 0) ? py - 1 : 0;
            if (inb(gx, gy)) { ownx = (d & 1) ? 0 : (px - 1); owny = (d & 2) ? 0 : (py - 1); }
            found = -1;
            // neighbor exists only if the wrap-around block shares this edge
            bool sharex = ((d & 1) && rx == 0) || ((d & 1) && rx == px - 1);
            bool sharey = ((d & 2) && ry == 0) || ((d & 2) && ry == py - 1);
            if (!sharex || !sharey) found = -1;
            else if (inb(gx, gy)) {
              // determine the wrap owner directly
              int owx = ((d & 1) ? ((rx == 0) ? px - 1 : 0) : -999);
              (void)owx;
              found = (d & 2) ? ((ry == 0) ? (px - 1 - 0 + 0) * 0 + 0 : 0) : 0; // resolved below
              found = -2; // marker: resolved via owner lookup
            }
          } else {
            found = nry * px + nrx;
          }
          if (found == -2) {
            // owner of the point on the wrap edge
            int ex = (d & 1) ? (rx == 0 ? 0 : px - 1) : -1;
            int ey = (d & 2) ? (ry == 0 ? 0 : py - 1) : -1;
            int ownx2 = (d & 1) ? (rx == 0 ? px - 1 : 0) : nrx;
            int owny2 = (d & 2) ? (ry == 0 ? py - 1 : 0) : nry;
            (void)ex; (void)ey;
            found = -1;
            for (int k = 0; k < px; k++) {
              int bx0 = (int)std::llround(k * S / px);
              int bx1 = (k == px - 1) ? (int)S : (int)std::llround((k + 1) * S / px);
              int probe = (d & 1) ? (rx == 0 ? bx0 : bx1) : 0;
              if ((d & 1) && probe >= bx0 && probe < bx1) { ownx2 = k; break; }
            }
            for (int k = 0; k < py; k++) {
              int by0 = (int)std::llround(k * S / py);
              int by1 = (k == py - 1) ? (int)S : (int)std::llround((k + 1) * S / py);
              int probe = (d & 2) ? (ry == 0 ? by0 : by1) : 0;
              if ((d & 2) && probe >= by0 && probe < by1) { owny2 = k; break; }
            }
            found = owny2 * px + ownx2;
          }
          if (found < 0 || found >= nprocs) found = -1;
        } else {
          found = -1;
        }
      }
      cand[d][0] = 0; cand[d][1] = 0;
      (void)found;
      nbr[d] = found;
      (void)cx[d]; (void)cy[d];
    }
    (void)inb; (void)px0; (void)px1; (void)py0; (void)py1;
  }

  // ----- buffers ----------------------------------------------------------
  std::vector<int> rcnts(2 * nprocs, 0), rsnds(2 * nprocs, 0);
  std::vector<int> recs, send;
  std::vector<double> rx, ry, rvx, rvy, sx, sy, svx, svy;
  // static send/recv counts are known up front
  if (dynamic) {
    for (int d = 0; d < 8; d++) {
      if (nbr[d] >= 0) {
        // send halo across face d to nbr[d]
        int w = (d & 1) ? 1 : 1;  // face thickness in cells
        int len;
        if (d == 0) len = RCi * (cr[3] - cr[2] + 2 * RCi);      // +x face (incl. corner overlap)
        else if (d == 1) len = RCi * (cr[3] - cr[2] + 2 * RCi);
        else if (d == 2) len = (cr[1] - cr[0] + 2 * RCi) * RCi;
        else len = (cr[1] - cr[0] + 2 * RCi) * RCi;
        (void)w;
        rsnds[2 * d] = len;
        rcnts[2 * nbr[d]] = len;
      }
    }
    int tot_s = 0, tot_r = 0;
    for (int r = 0; r < nprocs; r++) { tot_s += rsnds[2 * r]; tot_r += rcnts[2 * r]; }
    send.resize(4 * tot_s);
    recs.resize(4 * tot_r);
    sx.resize(tot_s); sy.resize(tot_s); svx.resize(tot_s); svy.resize(tot_s);
    rx.resize(tot_r); ry.resize(tot_r); rvx.resize(tot_r); rvy.resize(tot_r);
  }

  std::vector<double> myx(s.x.size()), myy, myvx, myvy, ax, ay;
  std::vector<int> sendcount, senddisp, recvcount, recvdisk;
  std::vector<double> gath_x, gath_y, gath_vx, gath_vy, scat_x, scat_y, scat_vx, scat_vy;
  std::vector<int> loc;

  auto t0 = std::chrono::steady_clock::now();
  for (int step = 0; step < NSTEP; step++) {
    if (dynamic) {
      // ---- local + ghost binning ----
      int gw = (cr[1] - cr[0]) + 2 * RCi;
      int gh = (cr[3] - cr[2]) + 2 * RCi;
      double gx0 = cr[0] - RCi, gy0 = cr[2] - RCi;
      std::vector<int> gcount(gw * gh, 0), gstart(gw * gh + 1, 0), gp(s.x.size());
      for (size_t i = 0; i < s.x.size(); i++) {
        double wx = s.x[i] - gx0, wy = s.y[i] - gy0;
        int cx = (int)(wx / RC);
        int cy = (int)(wy / RC);
        cx = std::max(0, std::min(gw - 1, cx));
        cy = std::max(0, std::min(gh - 1, cy));
        gcount[cy * gw + cx]++;
      }
      int run = 0;
      for (int c = 0; c < gw * gh; c++) { gstart[c] = run; run += gcount[c]; gcount[c] = 0; }
      gstart[gw * gh] = run;
      for (size_t i = 0; i < s.x.size(); i++) {
        double wx = s.x[i] - gx0, wy = s.y[i] - gy0;
        int cx = (int)(wx / RC);
        int cy = (int)(wy / RC);
        cx = std::max(0, std::min(gw - 1, cx));
        cy = std::max(0, std::min(gh - 1, cy));
        int c = cy * gw + cx;
        gp[gstart[c] + gcount[c]++] = (int)i;
      }
      // ---- fill send halo (particles straddling each of my 4 faces) ----
      int off = 0;
      double lox = cr[0], loy = cr[2];
      auto face_particles = [&](int face) -> std::vector<size_t> {
        // face: 0:+x 1:-x 2:+y 3:-y
        std::vector<size_t> v;
        double a = (face == 0) ? cr[1] - RCi : (face == 1 ? lox : 0.0);
        double b = (face == 0) ? cr[1] + RCi : (face == 1 ? lox + RCi : 0.0);
        double c = (face == 2) ? cr[3] - RCi : (face == 3 ? loy : 0.0);
        double d = (face == 2) ? cr[3] + RCi : (face == 3 ? loy + RCi : 0.0);
        for (size_t i = 0; i < s.x.size(); i++) {
          if (face < 2 ? (s.x[i] >= a && s.x[i] < b) : (s.y[i] >= c && s.y[i] < d))
            v.push_back(i);
        }
        return v;
      };
      for (int face = 0; face < 4; face++) {
        int d = face;  // 0:+x 1:-x 2:+y 3:-y match nbr layout
        auto v = face_particles(face);
        for (size_t i : v) {
          send[off * 4 + 0] = s.x[i];
          send[off * 4 + 1] = s.y[i];
          send[off * 4 + 2] = s.vx[i];
          send[off * 4 + 3] = s.vy[i];
          off++;
        }
        (void)d;
      }
      // halo length per face computed as full ghost-face strip: RC cells along the
      // perpendicular direction spanning the full local+ghost extent, so the
      // counts above (RCi * (other + 2RC)) match exactly when particles are
      // spread; to stay consistent we actually send every particle inside the
      // face strip, so recompute rcnts from send sizes instead.
      std::vector<int> sc(8, 0);
      for (int face = 0; face < 4; face++) sc[face] = (int)face_particles(face).size();
      for (int d = 0; d < 8; d++) {
        if (nbr[d] >= 0) {
          int len = (d < 4) ? sc[d] : 0;  // edges only; corners covered by both faces
          // corner cells are shared by two faces; to keep exact consistency we
          // send corners only with the +x/+y faces (d=0,2) — adjust counts.
          rsnds[2 * d] = len;
          rcnts[2 * nbr[d]] = len;
        }
      }
      // NOTE: face strips overlap on corners, and each rank's strip is exactly
      // the union of its 4 face strips, which is precisely the ghost layer.
      int tot_r = 0;
      for (int r = 0; r < nprocs; r++) tot_r += rcnts[2 * r];
      recs.resize(4 * tot_r);
      rx.resize(tot_r); ry.resize(tot_r); rvx.resize(tot_r); rvy.resize(tot_r);
      int send_off[9];
      int o = 0;
      for (int r = 0; r < nprocs; r++) { send_off[r] = o; o += rsnds[2 * r]; }
      send_off[nprocs] = o;
      int recv_off[nprocs + 1];
      std::vector<int> recvcnts(nprocs), recvdsp(nprocs + 1), senddsp(nprocs + 1);
      for (int r = 0; r < nprocs; r++) {
        senddsp[r] = send_off[r];
        recvcnts[r] = rcnts[2 * r];
      }
      senddsp[nprocs] = send_off[nprocs];
      recvdsp[0] = 0;
      for (int r = 0; r < nprocs; r++) recvdsp[r + 1] = recvdsp[r] + recvcnts[r];
      if (send_off[nprocs] > 0 || tot_r > 0) {
        MPI_Alltoallv(send.data(), rsnds.data(), senddsp.data(), MPI_DOUBLE,
                      recs.data(), recvcnts.data(), recvdsp.data(), MPI_DOUBLE, MPI_COMM_WORLD);
      }
      for (int r = 0; r < nprocs; r++)
        for (int k = 0; k < recvcnts[r]; k++) {
          int idx = recvdsp[r] + k;
          rx[idx] = recs[idx * 4 + 0];
          ry[idx] = recs[idx * 4 + 1];
          rvx[idx] = recs[idx * 4 + 2];
          rvy[idx] = recs[idx * 4 + 3];
        }
      // ---- assemble ghost particles into extended bins ----
      int nl = (int)s.x.size();
      std::vector<int> ext(gp.begin(), gp.end());
      ext.resize(nl + 0);
      // ghost particles appended after local ones: store their coords in rx/ry
      // Build per-cell index lists directly with a second counting pass.
      std::vector<int> ccount(gw * gh, 0);
      for (int i = 0; i < nl; i++) {
        int cx = (int)((s.x[i] - gx0) / RC);
        int cy = (int)((s.y[i] - gy0) / RC);
        cx = std::max(0, std::min(gw - 1, cx));
        cy = std::max(0, std::min(gh - 1, cy));
        ccount[cy * gw + cx]++;
      }
      for (int i = 0; i < tot_r; i++) {
        int cx = (int)((rx[i] - gx0) / RC);
        int cy = (int)((ry[i] - gy0) / RC);
        if (cx < 0 || cx >= gw || cy < 0 || cy >= gh) continue;
        ccount[cy * gw + cx]++;
      }
      std::vector<int> cstart(gw * gh + 1, 0);
      run = 0;
      for (int c = 0; c < gw * gh; c++) { cstart[c] = run; run += ccount[c]; ccount[c] = 0; }
      cstart[gw * gh] = run;
      std::vector<int> idxs(run);
      std::vector<double> ex(run), ey(run);
      for (int i = 0; i < nl; i++) {
        int cx = (int)((s.x[i] - gx0) / RC);
        int cy = (int)((s.y[i] - gy0) / RC);
        cx = std::max(0, std::min(gw - 1, cx));
        cy = std::max(0, std::min(gh - 1, cy));
        int c = cy * gw + cx;
        int slot = cstart[c] + ccount[c]++;
        idxs[slot] = i;
        ex[slot] = s.x[i];
        ey[slot] = s.y[i];
      }
      for (int i = 0; i < tot_r; i++) {
        int cx = (int)((rx[i] - gx0) / RC);
        int cy = (int)((ry[i] - gy0) / RC);
        if (cx < 0 || cx >= gw || cy < 0 || cy >= gh) continue;
        int c = cy * gw + cx;
        int slot = cstart[c] + ccount[c]++;
        idxs[slot] = -1 - i;  // ghost marker
        ex[slot] = rx[i];
        ey[slot] = ry[i];
      }
      // ---- forces on local particles from extended cells ----
      const double rc2 = RC * RC;
      ax.assign(nl, 0.0);
      ay.assign(nl, 0.0);
      for (int i = 0; i < nl; i++) {
        int cx = (int)((s.x[i] - gx0) / RC);
        int cy = (int)((s.y[i] - gy0) / RC);
        cx = std::max(0, std::min(gw - 1, cx));
        cy = std::max(0, std::min(gh - 1, cy));
        double fxi = 0.0, fyi = 0.0;
        for (int oy = -1; oy <= 1; oy++) {
          int yy = cy + oy;
          if (yy < 0 || yy >= gh) continue;
          for (int ox = -1; ox <= 1; ox++) {
            int xx = cx + ox;
            if (xx < 0 || xx >= gw) continue;
            int c = yy * gw + xx;
            for (int k = cstart[c]; k < cstart[c + 1]; k++) {
              int id = idxs[k];
              if (id >= 0 && id == i) continue;
              double dx = ex[k] - s.x[i];
              double dy = ey[k] - s.y[i];
              double r2 = dx * dx + dy * dy;
              if (r2 >= rc2 || r2 < 1e-12) continue;
              double r = std::sqrt(r2);
              double f = F0 * (1.0 - r / RC) / r;
              fxi -= f * dx;
              fyi -= f * dy;
            }
          }
        }
        ax[i] = fxi;
        ay[i] = fyi;
      }
      // ---- integrate local particles + wrap ----
      for (int i = 0; i < nl; i++) {
        s.vx[i] += DT * ax[i];
        s.vy[i] += DT * ay[i];
        if (s.vx[i] > VMAX) s.vx[i] = VMAX;
        else if (s.vx[i] < -VMAX) s.vx[i] = -VMAX;
        if (s.vy[i] > VMAX) s.vy[i] = VMAX;
        else if (s.vy[i] < -VMAX) s.vy[i] = -VMAX;
        s.x[i] += DT * s.vx[i];
        s.y[i] += DT * s.vy[i];
        s.x[i] = std::fmod(s.x[i], S);
        if (s.x[i] < 0.0) s.x[i] += S;
        s.y[i] = std::fmod(s.y[i], S);
        if (s.y[i] < 0.0) s.y[i] += S;
      }
      // ---- migrate particles that crossed block boundaries ----
      if ((step & 31) == 31) {
        int r0 = rank % px, r1 = rank / px;
        int sxp = S / px, syp = S / py;
        int x0 = (int)std::llround(r0 * (double)sxp);
        int x1 = (r0 == px - 1) ? (int)S : (int)std::llround((r0 + 1) * (double)sxp);
        int y0 = (int)std::llround(r1 * (double)syp);
        int y1 = (r1 == py - 1) ? (int)S : (int)std::llround((r1 + 1) * (double)syp);
        std::vector<size_t> out4[4];
        for (size_t i = 0; i < s.x.size(); i++) {
          if (s.x[i] >= x1) out4[0].push_back(i);
          else if (s.x[i] < x0) out4[1].push_back(i);
          else if (s.y[i] >= y1) out4[2].push_back(i);
          else if (s.y[i] < y0) out4[3].push_back(i);
        }
        int cnt4[4] = {(int)out4[0].size(), (int)out4[1].size(),
                       (int)out4[2].size(), (int)out4[3].size()};
        int rc4[4] = {0, 0, 0, 0};
        MPI_Alltoall(cnt4, 1, MPI_INT, rc4, 1, MPI_INT, MPI_COMM_WORLD);
        std::vector<double> sendv;
        for (int f = 0; f < 4; f++)
          for (size_t i : out4[f]) {
            sendv.push_back(s.x[i]); sendv.push_back(s.y[i]);
            sendv.push_back(s.vx[i]); sendv.push_back(s.vy[i]);
          }
        std::vector<double> recvv;
        int st[5], rv[5];
        st[0] = 0;
        for (int f = 0; f < 4; f++) st[f + 1] = st[f] + cnt4[f];
        rv[0] = 0;
        for (int f = 0; f < 4; f++) rv[f + 1] = rv[f] + rc4[f];
        std::vector<int> sc4(st.begin(), st.end() - 1), sd4(st.begin() + 1, st.end());
        std::vector<int> rc4v(rv.begin(), rv.end() - 1), rd4(rv.begin() + 1, rv.end());
        MPI_Alltoallv(sendv.data(), sc4.data(), sd4.data(), MPI_DOUBLE,
                      recvv.data(), rc4v.data(), rd4.data(), MPI_DOUBLE, MPI_COMM_WORLD);
        for (int f = 0; f < 4; f++) {
          for (int k = 0; k < rc4[f]; k++) {
            int idx = rd4[f] + k;
            s.x.push_back(recvv[idx * 4 + 0]);
            s.y.push_back(recvv[idx * 4 + 1]);
            s.vx.push_back(recvv[idx * 4 + 2]);
            s.vy.push_back(recvv[idx * 4 + 3]);
          }
        }
        std::vector<size_t> keep(s.x.size());
        for (size_t i = 0; i < s.x.size(); i++)
          if (!(out4[0].size() || out4[1].size() || out4[2].size() || out4[3].size()) ||
              (i >= s.x.size()))
            keep[i] = i;
        // drop outgoing particles: build keep list properly
        std::vector<char> gone(s.x.size() - (out4[0].size() + out4[1].size() + out4[2].size() + out4[3].size()), 0);
        std::vector<char> mask(s.x.size(), 0);
        // outgoing indices are the first cnt4 of the old array? No — compact in place:
        size_t w = 0;
        std::vector<char> outflag((int)s.x.size(), 0);
        // recompute: after push_backs, old particles are at [0, nl_old)
        int nl_old = (int)(s.x.size() - (rc4[0] + rc4[1] + rc4[2] + rc4[3]));
        for (int f = 0; f < 4; f++)
          for (size_t i : out4[f]) outflag[i] = 1;
        for (int i = 0; i < nl_old; i++) {
          if (!outflag[i]) {
            s.x[w] = s.x[i];
            s.y[w] = s.y[i];
            s.vx[w] = s.vx[i];
            s.vy[w] = s.vy[i];
            w++;
          }
        }
        for (int i = nl_old; i < (int)s.x.size(); i++) {
          s.x[w] = s.x[i];
          s.y[w] = s.y[i];
          s.vx[w] = s.vx[i];
          s.vy[w] = s.vy[i];
          w++;
        }
        s.x.resize(w);
        s.y.resize(w);
        s.vx.resize(w);
        s.vy.resize(w);
        (void)keep; (void)gone; (void)mask;
      }
    } else {
      // ---- static ownership fallback (small boxes): global binning per step
      std::vector<int> counts(nprocs, 0);
      for (int i = 0; i < n; i++) {
        int r = (int)std::min((long)((int)S - 1), (int)(s.x[i] / S * nprocs));
        counts[r]++;
      }
      std::vector<int> disp(nprocs + 1, 0);
      for (int r = 0; r < nprocs; r++) disp[r + 1] = disp[r] + counts[r];
      std::vector<int> sendi(n);
      for (int i = 0; i < n; i++) {
        int r = (int)std::min((long)((int)S - 1), (int)(s.x[i] / S * nprocs));
        sendi[disp[r] + counts[r]++] = i;
      }
      counts.assign(nprocs, 0);
      MPI_Allreduce(MPI_IN_PLACE, (int*)nullptr, 0, MPI_INT, MPI_SUM, MPI_COMM_WORLD); // no-op keep
      std::vector<int> rc(nprocs);
      MPI_Alltoall(counts.data(), 1, MPI_INT, rc.data(), 1, MPI_INT, MPI_COMM_WORLD);
      // Alltoallv of 4*n doubles
      std::vector<double> buf(4 * n);
      for (int i = 0; i < n; i++) {
        buf[i * 4 + 0] = s.x[i];
        buf[i * 4 + 1] = s.y[i];
        buf[i * 4 + 2] = s.vx[i];
        buf[i * 4 + 3] = s.vy[i];
      }
      std::vector<int> sc(nprocs), sd(nprocs + 1), rcv(nprocs), rd(nprocs + 1);
      for (int r = 0; r < nprocs; r++) {
        sc[r] = disp[r + 1] - disp[r];
        sd[r] = disp[r];
      }
      sd[nprocs] = n;
      int tot_r = 0;
      for (int r = 0; r < nprocs; r++) { rcv[r] = rc[r]; tot_r += rc[r]; }
      rd[0] = 0;
      for (int r = 0; r < nprocs; r++) rd[r + 1] = rd[r] + rc[r];
      std::vector<double> rbuf(4 * tot_r);
      if (n > 0)
        MPI_Alltoallv(buf.data(), sc.data(), sd.data(), MPI_DOUBLE,
                      rbuf.data(), rcv.data(), rd.data(), MPI_DOUBLE, MPI_COMM_WORLD);
      // global bins over [0,S)
      int cells = (int)(S + 0.5);
      int nc = cells * cells;
      std::vector<int> gcount(nc, 0), gstart(nc + 1, 0);
      for (int i = 0; i < tot_r; i++) {
        int cx = (int)(rbuf[i * 4 + 0] / RC);
        int cy = (int)(rbuf[i * 4 + 1] / RC);
        cx = std::min(cells - 1, std::max(0, cx));
        cy = std::min(cells - 1, std::max(0, cy));
        gcount[cy * cells + cx]++;
      }
      int run = 0;
      for (int c = 0; c < nc; c++) { gstart[c] = run; run += gcount[c]; gcount[c] = 0; }
      gstart[nc] = run;
      std::vector<int> gidx(run);
      for (int i = 0; i < tot_r; i++) {
        int cx = (int)(rbuf[i * 4 + 0] / RC);
        int cy = (int)(rbuf[i * 4 + 1] / RC);
        cx = std::min(cells - 1, std::max(0, cx));
        cy = std::min(cells - 1, std::max(0, cy));
        int c = cy * cells + cx;
        gidx[gstart[c] + gcount[c]++] = i;
      }
      const double rc2 = RC * RC;
      for (int i = 0; i < tot_r; i++) {
        double px = rbuf[i * 4 + 0], py = rbuf[i * 4 + 1];
        int cx = (int)(px / RC), cy = (int)(py / RC);
        cx = std::min(cells - 1, std::max(0, cx));
        cy = std::min(cells - 1, std::max(0, cy));
        double fxi = 0.0, fyi = 0.0;
        for (int oy = -1; oy <= 1; oy++) {
          int yy = cy + oy;
          if (yy < 0 || yy >= cells) continue;
          for (int ox = -1; ox <= 1; ox++) {
            int xx = cx + ox;
            if (xx < 0 || xx >= cells) continue;
            int c = yy * cells + xx;
            for (int k = gstart[c]; k < gstart[c + 1]; k++) {
              int j = gidx[k];
              if (j == i) continue;
              double dx = rbuf[j * 4 + 0] - px;
              double dy = rbuf[j * 4 + 1] - py;
              double r2 = dx * dx + dy * dy;
              if (r2 >= rc2 || r2 < 1e-12) continue;
              double r = std::sqrt(r2);
              double f = F0 * (1.0 - r / RC) / r;
              fxi -= f * dx;
              fyi -= f * dy;
            }
          }
        }
        double nvx = rbuf[i * 4 + 2] + DT * fxi;
        double nvy = rbuf[i * 4 + 3] + DT * fyi;
        if (nvx > VMAX) nvx = VMAX;
        else if (nvx < -VMAX) nvx = -VMAX;
        if (nvy > VMAX) nvy = VMAX;
        else if (nvy < -VMAX) nvy = -VMAX;
        double nx = px + DT * nvx;
        double ny = py + DT * nvy;
        nx = std::fmod(nx, S);
        if (nx < 0.0) nx += S;
        ny = std::fmod(ny, S);
        if (ny < 0.0) ny += S;
        rbuf[i * 4 + 0] = nx;
        rbuf[i * 4 + 1] = ny;
        rbuf[i * 4 + 2] = nvx;
        rbuf[i * 4 + 3] = nvy;
      }
      // scatter back (same partition as before, since counts per rank are equal)
      MPI_Alltoallv(rbuf.data(), rcv.data(), rd.data(), MPI_DOUBLE,
                    buf.data(), sc.data(), sd.data(), MPI_DOUBLE, MPI_COMM_WORLD);
      for (int i = 0; i < n; i++) {
        s.x[i] = buf[i * 4 + 0];
        s.y[i] = buf[i * 4 + 1];
        s.vx[i] = buf[i * 4 + 2];
        s.vy[i] = buf[i * 4 + 3];
      }
    }
  }
  auto t1 = std::chrono::steady_clock::now();
  double t = std::chrono::duration<double>(t1 - t0).count();

  // gather to rank 0
  std::vector<int> cn(nprocs), cd(nprocs + 1);
  int mycount = (int)s.x.size();
  MPI_Gather(&mycount, 1, MPI_INT, cn.data(), 1, MPI_INT, 0, MPI_COMM_WORLD);
  cd[0] = 0;
  for (int r = 0; r < nprocs; r++) cd[r + 1] = cd[r] + cn[r];
  std::vector<double> allx(cd[nprocs]), ally(cd[nprocs]);
  MPI_Gatherv(s.x.data(), mycount, MPI_DOUBLE, allx.data(), cn.data(), cd.data(), 0, MPI_COMM_WORLD);
  MPI_Gatherv(s.y.data(), mycount, MPI_DOUBLE, ally.data(), cn.data(), cd.data(), 0, MPI_COMM_WORLD);
  if (rank == 0) {
    Sim s2;
    s2.n = n;
    s2.size = S;
    s2.x = allx;
    s2.y = ally;
    s2.vx.resize(n, 0.0);
    s2.vy.resize(n, 0.0);
    report(s2, t, "procs", nprocs, out, sum);
  }
  MPI_Finalize();
  return 0;
}
